const agora = new Date(); // depende do momento em que corre
console.log(agora instanceof Date); // true

// Componentes: mês 2 é março, porque a contagem começa em 0
const porComponentes = new Date(2026, 2, 15);
console.log(porComponentes.getFullYear()); // 2026
console.log(porComponentes.getMonth()); // 2
console.log(porComponentes.getDate()); // 15

// String ISO só com data: interpretada como meia-noite UTC
const soData = new Date('2026-03-15');
console.log(soData.toISOString()); // "2026-03-15T00:00:00.000Z"

// String ISO com hora e sem Z: interpretada na hora local
const comHora = new Date('2026-03-15T00:00:00');
console.log(comHora.getHours()); // 0

// String ambígua: não é ISO, o V8 devolve Invalid Date
const ambigua = new Date('15/03/2026');
console.log(Number.isNaN(ambigua.getTime())); // true
console.log(String(ambigua)); // "Invalid Date"

const natal = new Date(2026, 11, 25); // 11 = dezembro
console.log(natal.getMonth()); // 11
console.log(natal.getDate()); // 25, o dia do mês
console.log(natal.getDay()); // 5, sexta-feira (0 = domingo)

// Date é mutável: setDate altera o próprio objeto
const marcada = new Date(2026, 0, 10);
const mesmaReferencia = marcada;
marcada.setDate(20);
console.log(mesmaReferencia.getDate()); // 20

// A defesa: copiar antes de modificar
function comDia(data, dia) {
  const copia = new Date(data);
  copia.setDate(dia);
  return copia;
}

const original = new Date(2026, 0, 10);
const alterada = comDia(original, 20);
console.log(original.getDate()); // 10
console.log(alterada.getDate()); // 20

const agoraMs = Date.now(); // depende do momento em que corre
console.log(typeof agoraMs); // "number"

const epoca = new Date(0);
console.log(epoca.toISOString()); // "1970-01-01T00:00:00.000Z"

const lancamento = new Date(Date.UTC(2026, 2, 15, 12, 30));
console.log(lancamento.getTime()); // 1773577800000
console.log(Number(lancamento) === lancamento.getTime()); // true

// Muitas APIs devolvem segundos, não milissegundos
const emSegundos = 1773577800;
console.log(new Date(emSegundos).getFullYear()); // 1970
console.log(new Date(emSegundos * 1000).toISOString()); // "2026-03-15T12:30:00.000Z"

// Uma data inválida tem timestamp NaN
const invalida = new Date('ontem à tarde');
console.log(Number.isNaN(invalida.getTime())); // true

const MS_POR_DIA = 24 * 60 * 60 * 1000;

const inicio = new Date(2026, 0, 1);
const fim = new Date(2026, 2, 1);
console.log(Math.round((fim - inicio) / MS_POR_DIA)); // 59

// Overflow automático: o dia 32 de janeiro é 1 de fevereiro
const transbordo = new Date(2026, 0, 32);
console.log(transbordo.getMonth()); // 1
console.log(transbordo.getDate()); // 1

// Dia 0 devolve o último dia do mês anterior: útil para saber quantos dias tem um mês
const ultimoDeFevereiro = new Date(2026, 2, 0);
console.log(ultimoDeFevereiro.getDate()); // 28

function somarDias(data, dias) {
  const copia = new Date(data);
  copia.setDate(copia.getDate() + dias);
  return copia;
}

const prazo = somarDias(new Date(2026, 0, 25), 10);
console.log(prazo.getMonth()); // 1
console.log(prazo.getDate()); // 4

const momento = new Date(Date.UTC(2026, 5, 10, 14, 0));

console.log(momento.toISOString()); // "2026-06-10T14:00:00.000Z"
console.log(momento.getUTCHours()); // 14

console.log(momento.toLocaleDateString('pt-PT', { timeZone: 'Europe/Lisbon' })); // "10/06/2026"
console.log(momento.toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' })); // "10/06/2026, 15:00:00"
console.log(momento.toLocaleTimeString('pt-PT', { timeZone: 'UTC' })); // "14:00:00"
console.log(momento.toLocaleDateString('pt-PT', { dateStyle: 'long', timeZone: 'Europe/Lisbon' })); // "10 de junho de 2026"

// O desvio depende da máquina e da altura do ano
const desvioMinutos = momento.getTimezoneOffset();
console.log(typeof desvioMinutos); // "number"

// Dia local em texto ISO, sem passar por UTC
function diaLocalISO(data) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, '0');
  const dia = String(data.getDate()).padStart(2, '0');
  return `${ano}-${mes}-${dia}`;
}

console.log(diaLocalISO(new Date(2026, 5, 10))); // "2026-06-10"

const a = new Date(2026, 2, 15);
const b = new Date(2026, 2, 15);

console.log(a === b); // false, são dois objetos diferentes
console.log(a == b); // false, pela mesma razão
console.log(a.getTime() === b.getTime()); // true

const cedo = new Date(2026, 2, 1);
const tarde = new Date(2026, 2, 31);
console.log(cedo < tarde); // true
console.log(cedo >= tarde); // false

const datas = [new Date(2026, 5, 1), new Date(2026, 0, 1), new Date(2026, 2, 1)];
datas.sort((x, y) => x - y);
console.log(datas.map((d) => d.getMonth())); // [ 0, 2, 5 ]

function mesmoDia(d1, d2) {
  return d1.getFullYear() === d2.getFullYear()
    && d1.getMonth() === d2.getMonth()
    && d1.getDate() === d2.getDate();
}

console.log(mesmoDia(new Date(2026, 2, 15, 9, 0), new Date(2026, 2, 15, 23, 30))); // true
console.log(mesmoDia(new Date(2026, 2, 15), new Date(2026, 2, 16))); // false

// Temporal ainda não existe em todo o lado: verifique antes de usar
if (typeof Temporal === 'undefined') {
  console.log('Temporal indisponível neste motor: use @js-temporal/polyfill');
} else {
  const hoje = Temporal.Now.plainDateISO();
  console.log(hoje.toString()); // depende do dia em que corre

  const data = Temporal.PlainDate.from('2026-03-15');
  console.log(data.month); // 3, porque os meses vão de 1 a 12
  console.log(data.dayOfWeek); // 7, domingo (1 = segunda-feira)

  const depois = data.add({ days: 10 });
  console.log(depois.toString()); // "2026-03-25"
  console.log(data.toString()); // "2026-03-15", o original não mudou

  console.log(data.equals(Temporal.PlainDate.from('2026-03-15'))); // true
}

