function formatarData(data) {
  const dia = String(data.getDate()).padStart(2, '0');
  const mes = String(data.getMonth() + 1).padStart(2, '0');
  const ano = data.getFullYear();
  return `${dia}/${mes}/${ano}`;
}

console.log(formatarData(new Date(2026, 2, 15))); // "15/03/2026"
console.log(formatarData(new Date(2026, 11, 1))); // "01/12/2026"
console.log(formatarData(new Date(2026, 0, 9))); // "09/01/2026"

const MS_POR_DIA = 24 * 60 * 60 * 1000;

function diasEntre(inicio, fim) {
  const a = Date.UTC(inicio.getFullYear(), inicio.getMonth(), inicio.getDate());
  const b = Date.UTC(fim.getFullYear(), fim.getMonth(), fim.getDate());
  return Math.round((b - a) / MS_POR_DIA);
}

console.log(diasEntre(new Date(2026, 0, 1), new Date(2026, 0, 31))); // 30
console.log(diasEntre(new Date(2026, 2, 1), new Date(2026, 3, 1))); // 31
console.log(diasEntre(new Date(2026, 3, 1), new Date(2026, 2, 1))); // -31
console.log(diasEntre(new Date(2026, 1, 10, 23, 59), new Date(2026, 1, 11, 0, 1))); // 1

function proximoDiaUtil(data) {
  const resultado = new Date(data);
  do {
    resultado.setDate(resultado.getDate() + 1);
  } while (resultado.getDay() === 0 || resultado.getDay() === 6);
  return resultado;
}

const sexta = new Date(2026, 2, 13);
console.log(sexta.getDay()); // 5, sexta-feira

const seguinte = proximoDiaUtil(sexta);
console.log(seguinte.getDate()); // 16
console.log(seguinte.getMonth()); // 2
console.log(seguinte.getDay()); // 1, segunda-feira
console.log(sexta.getDate()); // 13, o original não foi alterado

const quarta = new Date(2026, 2, 11);
console.log(proximoDiaUtil(quarta).getDate()); // 12

function diaLocalISO(data) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, '0');
  const dia = String(data.getDate()).padStart(2, '0');
  return `${ano}-${mes}-${dia}`;
}

function intervaloDeDatas(inicio, fim) {
  const dias = [];
  const cursor = new Date(inicio.getFullYear(), inicio.getMonth(), inicio.getDate());
  const limite = new Date(fim.getFullYear(), fim.getMonth(), fim.getDate());

  while (cursor <= limite) {
    dias.push(diaLocalISO(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }

  return dias;
}

console.log(intervaloDeDatas(new Date(2026, 1, 26), new Date(2026, 2, 2)));
// [ '2026-02-26', '2026-02-27', '2026-02-28', '2026-03-01', '2026-03-02' ]

console.log(intervaloDeDatas(new Date(2026, 2, 5, 18, 0), new Date(2026, 2, 5, 3, 0)).length); // 1
console.log(intervaloDeDatas(new Date(2026, 2, 6), new Date(2026, 2, 5))); // []
